define(["jquery","setServiceLabel","overlay","resetAllMessages","showErrorMessage",'mage/translate'],function($,setServiceLabel,overlay,resetAllMessages,showErrorMessage){return function(config,serviceStatus,isAlreadyConfigured){let requestStateSpan=$('#request_state_span');let requestStateMsgSpan=$('#fastly_request_state_message_span');let forceTls=true;let successTlsBtnMsg=$('#fastly-success-tls-button-msg');let errorTlsBtnMsg=$('#fastly-error-tls-button-msg');let warningTlsBtnMsg=$('#fastly-warning-tls-button-msg');let active_version=serviceStatus.active_version;requestStateSpan.find('.processing').show();let tlsOptions={id:'fastly-tls-options',title:jQuery.mage.__(' '),content:function(){return document.getElementById('fastly-tls-template').textContent;},actionOk:function(){toggleTls(active_version);}};getTlsSetting(active_version,false).done(function(response){requestStateSpan.find('.processing').hide();let tlsStateEnabled=requestStateMsgSpan.find('#force_tls_state_enabled');let tlsStateDisabled=requestStateMsgSpan.find('#force_tls_state_disabled');if(response.status===true){if(tlsStateDisabled.is(":hidden")){tlsStateEnabled.show();}}else if(response.status===false){if(tlsStateEnabled.is(":hidden")){tlsStateDisabled.show();}}else{requestStateMsgSpan.find('#force_tls_state_unknown').show();}}).fail(function(){requestStateSpan.find('.processing').hide();requestStateMsgSpan.find('#force_tls_state_unknown').show();});function getTlsSetting(active_version,loaderVisibility){return $.ajax({type:"POST",url:config.checkTlsSettingUrl,showLoader:loaderVisibility,data:{'active_version':active_version}});}
$('#fastly_force_tls_button').on('click',function(){if(isAlreadyConfigured!==true){$(this).attr('disabled',true);return alert($.mage.__('Please save config prior to continuing.'));}
resetAllMessages();$.ajax({type:"GET",url:config.serviceInfoUrl,showLoader:true}).done(function(service){if(service.status===false){return errorTlsBtnMsg.text($.mage.__('Please check your Service ID and API token and try again.')).show();}
active_version=service.active_version;let next_version=service.next_version;let service_name=service.service.name;getTlsSetting(active_version,true).done(function(response){overlay(tlsOptions);setServiceLabel(active_version,next_version,service_name);let upload_button=$('.upload-button span');if(response.status===false){$('.modal-title').text($.mage.__('You are about to enable Force TLS'));upload_button.text('Enable');}else{$('.modal-title').text($.mage.__('You are about to disable Force TLS'));upload_button.text('Disable');}
forceTls=response.status;}).fail(function(){showErrorMessage($.mage.__('An error occurred while processing your request. Please try again.'))});}).fail(function(){return errorTlsBtnMsg.text($.mage.__('An error occurred while processing your request. Please try again.')).show();});});function toggleTls(active_version){let activate_tls_flag=false;if($('#fastly_activate_tls').is(':checked')){activate_tls_flag=true;}
$.ajax({type:"POST",url:config.toggleTlsSettingUrl,data:{'activate_flag':activate_tls_flag,'active_version':active_version},showLoader:true,success:function(response){if(response.status===true){modal.modal('closeModal');let disabledOrEnabled='disabled';let statusStr=$.mage.__('disabled');if(forceTls===false){disabledOrEnabled='enabled';statusStr=$.mage.__('enabled');}else{disabledOrEnabled='disabled';}
successTlsBtnMsg.text($.mage.__('Force TLS is successfully %1.').replace('%1',statusStr)).show();$('.request_tls_state_span').hide();if(disabledOrEnabled==='enabled'){requestStateMsgSpan.find('#force_tls_state_disabled').hide();requestStateMsgSpan.find('#force_tls_state_enabled').show();}else{requestStateMsgSpan.find('#force_tls_state_enabled').hide();requestStateMsgSpan.find('#force_tls_state_disabled').show();}}else{resetAllMessages();showErrorMessage(response.msg);}}});}}});